package com.taskmanager.service;
import com.taskmanager.dto.*; import com.taskmanager.entity.User; import com.taskmanager.repository.UserRepository; import com.taskmanager.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users; private final PasswordEncoder encoder;private final AuthenticationManager auth;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;encoder=e;auth=a;jwt=j;} public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.existsByEmail(email))throw new IllegalArgumentException("An account with this email already exists");User u=users.save(new User(r.name().trim(),email,encoder.encode(r.password())));return response(u);} public AuthResponse login(LoginRequest r){String email=r.email().trim().toLowerCase();auth.authenticate(new UsernamePasswordAuthenticationToken(email,r.password()));return response(users.findByEmail(email).orElseThrow());} public AuthResponse.UserInfo me(String email){User u=users.findByEmail(email).orElseThrow();return new AuthResponse.UserInfo(u.getId(),u.getName(),u.getEmail());}private AuthResponse response(User u){return new AuthResponse(jwt.generate(u.getEmail()),new AuthResponse.UserInfo(u.getId(),u.getName(),u.getEmail()));}}
